// The board, drawn. `T` carries the text that is editable; everything else is geometry.
export function drawBoard(T) {
/* ---------- board drawing (coordinates follow the source slide) ---------- */
const C={teal:"#0E8C8C",orange:"hsl(var(--aa-orange-hsl))",orangeD:"#E8790A",plum:"#7B2D7B",sh:"#F07A2E"};
const ROLE={po:["product-owner","PO",C.orange,"Product Owner"],d:["developers","D",C.teal,"Developers"],sm:["scrum-master","SM",C.plum,"Scrum Master"],sh:["stakeholders","SH",C.sh,"Stakeholders"]};
const esc=s=>s.replace(/&/g,"&amp;");
const link=(id,inner,label)=>`<a href="#${id}" data-id="${id}" aria-label="${label}">${inner}</a>`;

/* people: one joined head-and-shoulders figure, used for every accountability */
const BODY="M-10 15 V10 Q-10 1 0 1 Q10 1 10 10 V15 Z";
const fig=col=>`<circle cx="0" cy="-4.5" r="6" fill="${col}"/><path d="${BODY}" fill="${col}"/>`;
/* several people in one role: three identical figures stacked close, told apart by shade only.
   Same size as a figure standing on its own - the box grows, the figures do not shrink. */
const manyOf=col=>`<g transform="translate(-2.5 0)"><g transform="translate(5 -3.5)">${fig("#095454")}</g><g transform="translate(2.5 -1.75)">${fig("#0A6D6D")}</g>${fig(col)}</g>`;
/* groups: different roles side by side, every figure the same size.
   The Scrum Master sits further out than the Product Owner because the Developers are a STACK and
   it grows up and to the right - the darkest of the three teals was landing on the plum, and
   colours must not merge with what sits beside them. */
const grp=(l,r,c)=>`<g transform="translate(-12 -5)">${l}</g><g transform="translate(15 -5)">${r}</g><g transform="translate(0 1)">${c}</g>`;
const TEAM=grp(fig("hsl(var(--aa-orange-hsl))"),fig("#7B2D7B"),manyOf("#0E8C8C"));
const FS=1.9;
function roleGlyph(r,cx,cy,s){const [,lab,col]=ROLE[r];
  /* several people in one role: three identical figures stacked close, told apart by shade only */
  if(r==="d")return `<g transform="translate(${cx} ${cy}) scale(${(FS*s).toFixed(3)})">${manyOf(col)}<g transform="translate(-2.5 0)"><text x="0" y="12" text-anchor="middle" font-size="6" font-weight="800" fill="#fff">D</text></g></g>`;
  return `<g transform="translate(${cx} ${cy}) scale(${(FS*s).toFixed(3)})"><g transform="translate(0 -2.25)">${fig(col)}<text x="0" y="12" text-anchor="middle" font-size="6" font-weight="800" fill="#fff">${lab}</text></g></g>`}
function hex(cx,cy,r){const [id,,,name]=ROLE[r];return link(id,`<g class="hot">${roleGlyph(r,cx,cy,1)}</g>`,name)}
const tri=(x,y,a,b,c)=>hex(x,y,a)+hex(x+45,y+26,b)+hex(x,y+52,c);

function tag(x,y,w,label,id,stroke){const lines=label.split("|");const h=lines.length>1?38:28;
  return link(id,`<g class="hot"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" class="paper" stroke="${stroke||C.orange}" stroke-width="2"/>${lines.map((l,i)=>`<text x="${x+w/2}" y="${y+(lines.length>1?16+i*14:19)}" text-anchor="middle" font-size="12" font-weight="700" class="ink">${l}</text>`).join("")}</g>`,label.replace("|"," "))}

function doc(x,y,w,label,id,stroke){const h=44;const lines=label.split("|");
  const d=`M${x} ${y} h${w} v${h-6} q${-w/4} 9 ${-w/2} 0 t${-w/2} 0 z`;
  return link(id,`<g class="hot"><path d="${d}" class="paper" stroke="${stroke}" stroke-width="2"/>${lines.map((l,i)=>`<text x="${x+w/2}" y="${y+16+i*14}" text-anchor="middle" font-size="11.5" font-weight="700" class="ink">${l}</text>`).join("")}</g>`,label.replace("|"," "))}

function stack(x,y,w,label,id){let r="";for(let i=2;i>=0;i--)r+=`<rect x="${x+i*3}" y="${y+i*3}" width="${w}" height="36" class="paper" stroke="${C.orange}" stroke-width="1.6"/>`;
  const l=label.split("|");return link(id,`<g class="hot">${r}${l.map((t,i)=>`<text x="${x+w/2}" y="${y+15+i*13}" text-anchor="middle" font-size="11" font-weight="700" class="ink">${t}</text>`).join("")}</g>`,label.replace("|"," "))}

function cube(cx,cy){return `<polygon points="${cx},${cy-24} ${cx+22},${cy-12} ${cx},${cy} ${cx-22},${cy-12}" fill="#FFB24D"/><polygon points="${cx-22},${cy-12} ${cx},${cy} ${cx},${cy+25} ${cx-22},${cy+13}" fill="${C.orange}"/><polygon points="${cx+22},${cy-12} ${cx},${cy} ${cx},${cy+25} ${cx+22},${cy+13}" fill="${C.orangeD}"/>`}
const cubes=(a,b,c)=>link("increment",`<g class="hot">${[a,b,c].map(p=>icon("inc",p[0],p[1],52)).join("")}</g>`,"Increments");

function chevron(x1,x2,y,h,label,id,first){const n=9,m=y+h/2;
  const pts=first?`${x1},${y} ${x2-n},${y} ${x2},${m} ${x2-n},${y+h} ${x1},${y+h}`:`${x1},${y} ${x2-n},${y} ${x2},${m} ${x2-n},${y+h} ${x1},${y+h} ${x1+n},${m}`;
  return link(id,`<polygon class="bar" points="${pts}" fill="${C.plum}"/><text x="${(x1+x2)/2+ (first?0:4)}" y="${m+5}" text-anchor="middle" font-size="12" fill="#fff" class="lbl">${label}</text>`,label)}

function callout(x,y,w,label,id,fill,border,circ){const h=36;
  const tail=`${x+w-34},${y+h} ${x+w-14},${y+h} ${x+w-6},${y+h+16}`;
  return link(id,`<g class="hot"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}" ${border?`stroke="${border}" stroke-width="3"`:""}/><polygon points="${tail}" fill="${fill}" ${border?`stroke="${border}" stroke-width="3" stroke-linejoin="round"`:""}/><rect x="${x+w-34}" y="${y+h-3}" width="20" height="5" fill="${fill}"/><text x="${x+w/2}" y="${y+24}" text-anchor="middle" font-size="16" fill="#fff" class="lbl">${label}</text>
   <circle cx="${circ[0]}" cy="${circ[1]}" r="22" fill="${circ[2]}" stroke="${circ[3]}" stroke-width="4"/><text x="${circ[0]}" y="${circ[1]+8}" text-anchor="middle" font-size="22" font-weight="800" fill="#fff">${circ[4]}</text></g>`,label)}

function rail(x,y1,y2,label,id,col){const mid=(y1+y2)/2;
  return link(id,`<g class="hot"><line x1="${x}" y1="${y1+10}" x2="${x}" y2="${y2-10}" stroke="${col}" stroke-width="3"/><polygon points="${x-8},${y1+12} ${x+8},${y1+12} ${x},${y1}" fill="${col}"/><polygon points="${x-8},${y2-12} ${x+8},${y2-12} ${x},${y2}" fill="${col}"/>
   <text transform="translate(${x+18} ${mid}) rotate(90)" text-anchor="middle" font-size="12.5" fill="${col}" class="lbl">${label}</text></g>`,label)}

function wheel(cx,cy){const R=58,r=22,labels=["Commitment","Focus","Openness","Respect","Courage"],cols=[C.plum,"#E8664A","#F4B03C",C.teal,"#9BCB3B"];let s="";
  for(let i=0;i<5;i++){const a0=(-90+i*72)*Math.PI/180,a1=(-90+(i+1)*72)*Math.PI/180;
    const p=(a,rad)=>[cx+rad*Math.cos(a),cy+rad*Math.sin(a)].map(v=>v.toFixed(1)).join(" ");
    s+=`<path d="M${p(a0,r)} L${p(a0,R)} A${R} ${R} 0 0 1 ${p(a1,R)} L${p(a1,r)} A${r} ${r} 0 0 0 ${p(a0,r)}Z" fill="${cols[i]}"/>`;
    const am=(a0+a1)/2;s+=`<text x="${(cx+40*Math.cos(am)).toFixed(1)}" y="${(cy+40*Math.sin(am)+3).toFixed(1)}" text-anchor="middle" font-size="6.6" font-weight="700" fill="#fff">${labels[i]}</text>`}
  s+=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#111"/><text x="${cx}" y="${cy+4}" text-anchor="middle" font-size="10" font-weight="700" fill="#fff">Scrum</text>`;
  return link("scrum-values",`<g class="hot">${s}</g>`,"Scrum Values")}

let s=`<defs><marker id="arr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="${C.plum}"/></marker>
<linearGradient id="fade" x1="0" x2="1"><stop offset="0" stop-color="${C.teal}"/><stop offset="1" stop-color="${C.teal}" stop-opacity="0"/></linearGradient></defs>`;
/* artifact and commitment icons, drawn around (0,0); hexes have radius 46 */
const HEX46="0,-46 39.8,-23 39.8,23 0,46 -39.8,23 -39.8,-23";
const GEM=`<polygon points="-17,-5 -9,-13 9,-13 17,-5 0,15" fill="#FFFFFF"/><polygon points="-15,-5 -8,-11.5 8,-11.5 15,-5" fill="#5CC8C8"/><polygon points="-15,-5 15,-5 0,12.5" fill="#0E8C8C"/><path d="M-6 -3 l4 4 l8 -9" fill="none" stroke="#FFFFFF" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;
const ICON={
 pb:`<rect x="-31" y="-35" width="62" height="70" rx="11" fill="hsl(var(--aa-mid-teal-hsl))"/><polygon points="-12,-14 -4,-27 1,-20 5,-24 12,-14" fill="hsl(var(--aa-orange-hsl))"/><polygon points="-4,-27 -1.6,-23 -6.4,-23" fill="#FFFFFF"/><rect x="-7" y="-10" width="14" height="4" rx="2" fill="#E0A800"/><rect x="-12" y="-3" width="24" height="6" rx="2.5" fill="#FFC21A"/><rect x="-18" y="6" width="36" height="8" rx="3" fill="#FFD866"/><rect x="-24" y="17" width="48" height="10" rx="3.5" fill="#FFEBAD"/>`,
 sb:`<rect x="-31" y="-35" width="62" height="70" rx="11" fill="hsl(var(--aa-deep-teal-hsl))"/><line x1="-8" y1="-26" x2="-8" y2="-12" stroke="#FFFFFF" stroke-width="2.5" stroke-linecap="round"/><polygon points="-8,-26 7,-21 -8,-16" fill="hsl(var(--aa-orange-hsl))"/><rect x="-22" y="-7" width="8" height="8" rx="2" fill="hsl(var(--aa-orange-hsl))"/><rect x="-10" y="-6" width="32" height="6" rx="3" fill="#FFFFFF"/><rect x="-22" y="6" width="8" height="8" rx="2" fill="hsl(var(--aa-orange-hsl))"/><rect x="-10" y="7" width="32" height="6" rx="3" fill="#FFFFFF"/><rect x="-21" y="20" width="6" height="6" rx="1.5" fill="none" stroke="#FFFFFF" stroke-width="2"/><rect x="-10" y="20" width="32" height="6" rx="3" fill="#FFFFFF" opacity=".55"/>`,
 inc:`<polygon points="-39.8,-23 0,-46 39.8,-23 0,0" fill="#FFB24D"/><polygon points="0,0 39.8,-23 39.8,23 0,46" fill="#E07A00"/><polygon points="-39.8,-23 0,0 0,46 -39.8,23" fill="hsl(var(--aa-orange-hsl))"/><g transform="translate(30 30)">${GEM}</g>`,
 pg:`<polygon points="-26,18 -8,-16 2,-2 10,-12 26,18" fill="hsl(var(--aa-orange-hsl))"/><polygon points="-8,-16 -3,-7 -13,-7" fill="#FFFFFF"/><polygon points="10,-12 13,-6 7,-6" fill="#FFFFFF"/>`,
 sg:`<line x1="-6" y1="-20" x2="-6" y2="20" stroke="hsl(var(--aa-deep-teal-hsl))" stroke-width="3" stroke-linecap="round"/><polygon points="-6,-20 16,-12 -6,-4" fill="hsl(var(--aa-orange-hsl))"/>`,
 dod:`<g transform="scale(1.35)">${GEM}</g>`};
const CUBE=`<polygon points="-39.8,-23 0,-46 39.8,-23 0,0" fill="#FFB24D"/><polygon points="0,0 39.8,-23 39.8,23 0,46" fill="#E07A00"/><polygon points="-39.8,-23 0,0 0,46 -39.8,23" fill="hsl(var(--aa-orange-hsl))"/>`;
const PL="#7B2D7B";
const face=m=>`<circle cx="-2.1" cy="-5.3" r="0.8" fill="#fff"/><circle cx="2.1" cy="-5.3" r="0.8" fill="#fff"/><path d="${m}" fill="none" stroke="#fff" stroke-width="0.9" stroke-linecap="round"/>`;
const VIEWS=grp(fig("hsl(var(--aa-orange-hsl))")+face("M-2.5 -2.7 Q0 -0.6 2.5 -2.7"),fig("#7B2D7B")+face("M-2.5 -1.2 Q0 -3.3 2.5 -1.2"),fig("#0E8C8C")+face("M-2.4 -2 H2.4"));
const LOOP=`<path d="M5 -25.5 A26 26 0 1 1 -5 -25.5" fill="none" stroke="${PL}" stroke-width="3" stroke-linecap="round"/><polygon points="-8,-31 3,-25.5 -8,-20" fill="${PL}"/>`;
const BUB=(t)=>`<path d="M-7 -8 H7 Q11 -8 11 -4 V4 Q11 8 7 8 ${t} H-7 Q-11 8 -11 4 V-4 Q-11 -8 -7 -8 Z" fill="#FFFFFF" stroke="${PL}" stroke-width="1.6" stroke-linejoin="round"/>`;
Object.assign(ICON,{
 esprint:LOOP+`<g transform="scale(.33)">${CUBE}</g>`,
 eplan:`<g transform="translate(-12 -9) scale(.4)">${ICON.pb}</g><g transform="translate(13 12) scale(.4)">${ICON.sb}</g><path d="M2 -17 Q15 -17 15 -5" fill="none" stroke="${PL}" stroke-width="2.5" stroke-linecap="round"/><polygon points="10,-7 20,-7 15,0" fill="${PL}"/>`,
 edaily:`<path d="M5 -25.5 A26 26 0 1 1 -5 -25.5" fill="none" stroke="${PL}" stroke-width="2.5" stroke-dasharray="5 4" stroke-linecap="round"/><polygon points="-8,-31 3,-25.5 -8,-20" fill="${PL}"/><g transform="scale(.5)">${ICON.sb}</g>`,
 ereview:`<g transform="translate(-12 -17)">${BUB("H1 L-3 13 L-3 8")}<g transform="scale(.15)">${CUBE}</g></g><g transform="translate(12 -19)">${BUB("H3 L3 13 L-1 8")}<polygon transform="scale(.3)" points="-26,18 -8,-16 2,-2 10,-12 26,18" fill="hsl(var(--aa-orange-hsl))"/></g><g transform="translate(0 12) scale(.72)">${VIEWS}</g>`,
 eretro:`<path d="M-5 -25.5 A26 26 0 1 0 5 -25.5" fill="none" stroke="${PL}" stroke-width="3" stroke-linecap="round"/><polygon points="8,-31 -3,-25.5 8,-20" fill="${PL}"/><g transform="translate(0 1) scale(.7)">${TEAM}</g>`,
 team:`<g transform="translate(0 -1)">${TEAM}</g>`,
 perf:`<line x1="-25" y1="22" x2="25" y2="22" stroke="hsl(var(--aa-deep-teal-hsl))" stroke-width="2.5" stroke-linecap="round"/><rect x="-20" y="4" width="10" height="18" rx="2" fill="#0E8C8C"/><rect x="-5" y="-6" width="10" height="28" rx="2" fill="#0E8C8C"/><rect x="10" y="-1" width="10" height="23" rx="2" fill="#0E8C8C"/><line x1="-26" y1="-14" x2="26" y2="-14" stroke="hsl(var(--aa-orange-hsl))" stroke-width="3" stroke-dasharray="5 3" stroke-linecap="round"/>`,
 env:`<circle cx="0" cy="0" r="17" fill="hsl(var(--aa-pale-teal-hsl))" stroke="hsl(var(--aa-mid-teal-hsl))" stroke-width="2.5"/><ellipse cx="0" cy="0" rx="7" ry="17" fill="none" stroke="hsl(var(--aa-mid-teal-hsl))" stroke-width="2"/><line x1="-17" y1="0" x2="17" y2="0" stroke="hsl(var(--aa-mid-teal-hsl))" stroke-width="2"/><path d="M-11 -22 A24 24 0 0 1 21 -11" fill="none" stroke="hsl(var(--aa-orange-hsl))" stroke-width="3" stroke-linecap="round"/><polygon points="16,-14 27,-13 21,-4" fill="hsl(var(--aa-orange-hsl))"/><path d="M11 22 A24 24 0 0 1 -21 11" fill="none" stroke="hsl(var(--aa-orange-hsl))" stroke-width="3" stroke-linecap="round"/><polygon points="-16,14 -27,13 -21,4" fill="hsl(var(--aa-orange-hsl))"/>`,
 imp:`<rect x="-24" y="8" width="14" height="14" rx="2" fill="#7B2D7B"/><rect x="-10" y="-2" width="14" height="24" rx="2" fill="#7B2D7B"/><rect x="4" y="-12" width="14" height="34" rx="2" fill="#7B2D7B"/><rect x="9" y="-25" width="4" height="10" fill="hsl(var(--aa-orange-hsl))"/><polygon points="3,-23 19,-23 11,-31" fill="hsl(var(--aa-orange-hsl))"/>`,
 how:`<g transform="translate(-10 4) scale(1.3)">${fig("#0E8C8C")}</g><g transform="translate(13 -6)" fill="#7B2D7B">${[0,45,90,135,180,225,270,315].map(a=>`<rect x="-2.5" y="-12.5" width="5" height="6" rx="1" transform="rotate(${a})"/>`).join("")}<circle r="8.5"/><circle r="3.2" fill="#FFFFFF"/></g>`});
const ICONSIZE={perf:27,env:27,imp:31,how:27,pb:35,sb:35,inc:46,pg:26,sg:22,dod:22,esprint:31,eplan:27,edaily:31,ereview:30,eretro:31,team:22};
const icon=(k,x,y,px)=>`<g transform="translate(${x} ${y}) scale(${(px/2/ICONSIZE[k]).toFixed(3)})">${ICON[k]}</g>`;
/* ---------- extra shapes ---------- */
function teamHex(cx,cy,r){return link("scrum-team",`<g class="hot"><g transform="translate(${cx} ${cy}) scale(${(r>=30?FS:FS*.6).toFixed(3)})"><g transform="translate(0 -1)">${TEAM}</g></g></g>`,"Scrum Team")}
function hexPts(x,y,s){return [[x-30*s,y],[x-15*s,y-26*s],[x+15*s,y-26*s],[x+30*s,y],[x+15*s,y+26*s],[x-15*s,y+26*s]].map(p=>p.map(v=>v.toFixed(1)).join(",")).join(" ")}
function devStack(cx,cy,s=1){ // Developers: stacked hexes, because there is usually more than one
  return link("developers",`<g class="hot">${roleGlyph("d",cx,cy,s)}</g>`,"Developers")}
function downArrow(cx,y,col){return `<polygon points="${cx-6},${y} ${cx+6},${y} ${cx+6},${y+8} ${cx+13},${y+8} ${cx},${y+20} ${cx-13},${y+8} ${cx-6},${y+8}" fill="${col}"/>`}

/* input / output chips laid out to fit each column */
const CW=6.5;
const STROKE={pb:C.teal,sb:C.teal,inc:C.orangeD,pg:C.orange,sg:C.orange,dod:C.orange};
const ISZ=38;
function itemSize(it){if(it.k!=="info")return [ISZ,ISZ];const ls=it.t.split("|");return [Math.max(Math.max(...ls.map(l=>l.length))*CW+18,56),ls.length*13+14]}
function drawItem(it,x,y,w,h){
  if(it.k!=="info")return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="transparent"/>${icon(it.k,x+w/2,y+h/2,w)}`;
  const ls=it.t.split("|"),top=y+h/2-(ls.length-1)*6.5+4;
  return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" class="ia-in" stroke="#9CA3AF" stroke-width="1.4" stroke-dasharray="4 3"/>`+ls.map((l,i)=>`<text x="${x+w/2}" y="${top+i*13}" text-anchor="middle" font-size="${i===0?11:10}" font-weight="${i===0?700:500}" class="${i===0?"ink":"muted"}">${l}</text>`).join("")}
function flow(items,x1,x2,y){items=[...items.filter(i=>i.k!=="info"),...items.filter(i=>i.k==="info")];const inner=x2-x1-12,gap=8;const rows=[];let row=[],rw=0;
  items.forEach(it=>{const [w,h]=itemSize(it),W=Math.min(w,inner);if(row.length&&rw+gap+W>inner){rows.push(row);row=[];rw=0}rw+=(row.length?gap:0)+W;row.push([it,W,h])});if(row.length)rows.push(row);
  let out="",cy=y;rows.forEach(r=>{const tw=r.reduce((a,b)=>a+b[1],0)+gap*(r.length-1);let cx=(x1+x2)/2-tw/2;const rh=Math.max(...r.map(b=>b[2]));
    r.forEach(([it,w,h])=>{out+=link(it.id,`<g class="hot">${drawItem(it,cx,cy+(rh-h)/2,w,h)}</g>`,it.t.replace("|",": ").replace(/\|/g," "));cx+=w+gap});cy+=rh+gap});
  return [out,cy-gap-y]}
const wrapW=(t,w,cw)=>{const max=Math.floor((w-16)/cw),out=[];let line="";t.split(" ").forEach(word=>{if((line+" "+word).trim().length>max&&line){out.push(line);line=word}else line=(line+" "+word).trim()});out.push(line);return out};

/* ---------- the board ---------- */
const COLS=[[170,320],[320,688],[688,882],[882,1028]];
const EVENTS=["sprint-planning","daily-scrum","sprint-review","sprint-retrospective"];
const INPUTS=T.INPUTS;
const OUTPUTS=T.OUTPUTS;
const DESC=T.DESC;

/* sprint bar + wheel + events */
/* values wheel stays top right; Sprint bar and events now sit just above the board */
s+=wheel(1128,60);


/* inputs row */
const yIn=24;const ins=INPUTS.map((list,i)=>flow(list,...COLS[i],yIn));const hIn=Math.max(...ins.map(x=>x[1]));
ins.forEach(x=>s+=x[0]);
const rowLabel=(y,h,title,sub,fill,txt)=>link("inspect-adapt",`<g class="rowlab"><rect x="40" y="${y}" width="120" height="${h}" rx="8" fill="${fill}"/><text x="100" y="${y+h/2-2}" text-anchor="middle" font-size="12" class="lbl" fill="${txt}">${title}</text><text x="100" y="${y+h/2+14}" text-anchor="middle" font-size="10.5" font-weight="500" fill="${txt}">${sub}</text></g>`,title.toLowerCase());
s+=rowLabel(yIn,hIn,"INPUTS","inspected",C.teal,"#fff");
const yArr1=yIn+hIn+4;COLS.forEach(([a,b])=>s+=downArrow((a+b)/2,yArr1,C.orange));

/* board frame */
const yBar=yArr1+28;
s+=`<g transform="translate(0 ${yBar-76})">`+link("sprint",`<polygon class="bar" points="170,76 1022,76 1034,88 1022,100 170,100" fill="${C.teal}"/><polygon points="1036,76 1080,76 1080,100 1036,100 1048,88" fill="url(#fade)"/><text x="600" y="93" text-anchor="middle" font-size="15" fill="#fff" class="lbl">SPRINT</text>`,"Sprint")+chevron(170,318,106,24,"SPRINT PLANNING","sprint-planning",true)+chevron(320,688,106,24,"DAILY SCRUMS","daily-scrum")+chevron(690,880,106,24,"SPRINT REVIEW","sprint-review")+chevron(882,1028,106,24,"RETROSPECTIVE","sprint-retrospective")+"</g>";
const yB=yBar+66,yI=yB+34,yD=yB+66,hD=66,yC=yD+hD+10,Z=128,yE=yC+3*Z+2;
s+=`<rect x="170" y="${yB}" width="858" height="${yE-yB}" class="paper boardline" stroke-width="3"/>`;
[320,688,882].forEach(x=>s+=`<line x1="${x}" y1="${yB}" x2="${x}" y2="${yE}" class="boardline" stroke-width="3"/>`);
[yC+Z-2,yC+2*Z-2].forEach(y=>s+=`<line x1="170" y1="${y}" x2="320" y2="${y}" class="boardline" stroke-width="3" stroke-dasharray="14 8"/>`);

/* event icons: Sprint beside its bar, the four events at the top of their columns */
s+=link("sprint",`<g class="hot">${icon("esprint",146,yBar+12,38)}</g>`,"Sprint");
["eplan","edaily","ereview","eretro"].forEach((k,i)=>{const [a,b]=COLS[i];s+=link(EVENTS[i],`<g class="hot">${icon(k,(a+b)/2,yI,54)}</g>`,["Sprint Planning","Daily Scrum","Sprint Review","Sprint Retrospective"][i])});
/* inspect / adapt description inside each event */
DESC.forEach((pair,i)=>{const [a,b]=COLS[i];let lines=[];pair.forEach((t,j)=>wrapW(t,b-a-8,6.0).forEach((l,k)=>lines.push([l,j,k])));
  const lh=14,top=yD+hD/2-(lines.length-1)*lh/2+4;
  const txt=lines.map(([l,j,k],n)=>{const m=k===0&&l.match(/^(Inspect|Adapt|Create)\b/);return `<text x="${(a+b)/2}" y="${top+n*lh}" text-anchor="middle" font-size="11.5" class="ink">${m?`<tspan font-weight="800" class="${j?"verb-ad":"verb-in"}">${m[1]}</tspan>${l.slice(m[1].length)}`:l}</text>`}).join("");
  s+=link(EVENTS[i],`<g class="iacell"><rect x="${a+6}" y="${yD}" width="${b-a-12}" height="${hD}" rx="8" class="ia-in"/>${txt}</g>`,pair.join(", "))});

/* Sprint Planning topics */
const zc=k=>yC+k*Z;
s+=callout(32,zc(0)+8,104,"1. WHY?","topic-why",C.orangeD,null,[162,zc(0)+64,C.orangeD,"#fff","1"]);
s+=callout(40,zc(1)+8,106,"2. WHAT?","topic-what",C.teal,C.orange,[168,zc(1)+64,C.teal,C.orange,"2"]);
s+=callout(40,zc(2)+8,100,"3. HOW?","topic-how",C.teal,C.orange,[168,zc(2)+64,C.teal,C.orange,"3"]);
s+=flow([{t:"Sprint Goal",k:"sg",id:"sprint-goal"}],170,320,zc(0)+8)[0]+teamHex(245,zc(0)+82,33);
s+=flow([{t:"Product Backlog|items selected",k:"pb",id:"product-backlog"}],170,320,zc(1)+4)[0]+hex(214,zc(1)+90,"po")+devStack(272,zc(1)+90);
s+=flow([{t:"Sprint Backlog|actionable plan",k:"sb",id:"sprint-backlog"}],170,320,zc(2)+8)[0]+devStack(240,zc(2)+84);

/* Daily Scrums */
s+=hex(436,yC+100,"po")+devStack(504,yC+100)+hex(572,yC+100,"sm");
s+=cubes([474,yC+214],[544,yC+214],[509,yC+268]);
/* Sprint Review */
s+=teamHex(752,yC+150,36)+hex(830,yC+150,"sh");
/* Sprint Retrospective */
s+=teamHex(955,yC+150,36);

/* outputs row */
const yArr2=yE+4;COLS.forEach(([a,b])=>s+=downArrow((a+b)/2,yArr2,C.orange));
const yOut=yE+30;const outs=OUTPUTS.map((list,i)=>flow(list,...COLS[i],yOut));const hOut=Math.max(...outs.map(x=>x[1]));
outs.forEach(x=>s+=x[0]);
s+=rowLabel(yOut,hOut,"OUTPUTS","adapted or created",C.orange,"hsl(var(--aa-deep-teal-hsl))");

/* rails */
s+=rail(1054,yB,yOut+hOut,"SCRUM THEORY: EMPIRICISM · LEAN THINKING","scrum-theory",C.teal);
s+=rail(1098,yB,yOut+hOut,"PRODUCT BACKLOG REFINEMENT","refinement",C.orangeD);

/* values + legend (drawn at their original coordinates, shifted down) */
const dy=yOut+hOut+26-700;
s+=`<g transform="translate(0 ${dy})">`;
s+=link("scrum-values",`<path d="M172 700 v8 h846 v-8" fill="none" stroke="#9CA3AF" stroke-width="2"/><text x="595" y="730" text-anchor="middle" font-size="13" class="ink lbl ul">SCRUM VALUES</text>`,"Scrum Values");
const lg=(x,r)=>{const [id,,,name]=ROLE[r];
  return link(id,`<g class="hot">${roleGlyph(r,x,768,.6)}<text x="${x+(r==="d"?36:28)}" y="773" font-size="14" font-weight="500" class="ink">${name}</text></g>`,name)};
s+=lg(70,"po")+lg(258,"d")+lg(415,"sm")+lg(565,"sh");
[["esprint","sprint","Sprint",70],["eplan","sprint-planning","Sprint Planning",255],["edaily","daily-scrum","Daily Scrum",450],["ereview","sprint-review","Sprint Review",620],["eretro","sprint-retrospective","Retrospective",800]].forEach(([k,id,name,x])=>{
  s+=link(id,`<g class="hot">${icon(k,x,866,34)}<text x="${x+26}" y="871" font-size="14" font-weight="500" class="ink">${name}</text></g>`,name)});
[["imp","sprint-retrospective","Improvements",70],["perf","topic-what","Past Performance & Capacity",255],["env","sprint-review","Changes in the Environment",530],["how","sprint-retrospective","How the Sprint Went",800]].forEach(([k,id,name,x])=>{
  s+=link(id,`<g class="hot">${icon(k,x,914,32)}<text x="${x+26}" y="919" font-size="14" font-weight="500" class="ink">${name}</text></g>`,name)});
s+=teamHex(745,767,19).replace('aria-label="Scrum Team">','aria-label="Scrum Team"><text x="775" y="773" font-size="14" font-weight="500" class="ink">Scrum Team</text>');
s+=`<text x="871" y="773" font-size="12" class="muted">= PO + SM + Developers</text>`;
[["pb","product-backlog","Product Backlog",70],["sb","sprint-backlog","Sprint Backlog",255],["inc","increment","Increment",430],["pg","product-goal","Product Goal",585],["sg","sprint-goal","Sprint Goal",755],["dod","definition-of-done","Definition of Done",905]].forEach(([k,id,name,x])=>{
  s+=link(id,`<g class="hot">${icon(k,x,816,k==="inc"?34:30)}<text x="${x+24}" y="821" font-size="14" font-weight="500" class="ink">${name}</text></g>`,name)});
s+="</g>";
const VBH=928+dy+24;

  return { svg: s, height: VBH };
}
